# Experiment 4A: export ggplot2 and base R graphics to PNG files.
source("r/common.R"); library(ggplot2); d<-load_students(); p<-ggplot(d,aes(Student,Math,group=1))+geom_line(colour="#4776A8",linewidth=1)+geom_point(colour="#D98B55",size=2.5)+labs(title="Mathematics Scores",x="Student",y="Math score")+theme_minimal()+theme(axis.text.x=element_text(angle=35,hjust=1)); ggsave(save_plot_path("4A_ggplot_export.png"),p,width=8,height=5,dpi=200); png(save_plot_path("4A_base_r_export.png"),1200,750,res=150); barplot(colMeans(d[subjects]),main="Average Subject Scores",xlab="Subject",ylab="Average score",ylim=c(0,100),col=c("#4776A8","#55A889","#D98B55"),border=NA); dev.off(); cat("Charts exported to",output_dir,"\n")
